216	    private ElementMeta createSafeElement(Element sourceEl) {
217	        Element dest = sourceEl.shallowClone(); // reuses tag, clones attributes and preserves any user data
218	        String sourceTag = sourceEl.tagName();
219	        Attributes destAttrs = dest.attributes();
220	        dest.clearAttributes(); // clear all non-internal attributes, ready for safe copy
221	
222	        int numDiscarded = 0;
223	        Attributes sourceAttrs = sourceEl.attributes();
224	        for (Attribute sourceAttr : sourceAttrs) {
225	            if (safelist.isSafeAttribute(sourceTag, sourceEl, sourceAttr)) { // will keep this attr
226	                String key = sourceAttr.getKey();
227	                String value = sourceAttr.getValue();
228	
229	                if (Safelist.isSrcset(key)) { // clean the srcset candidates; drop the attribute if none survive
230	                    String cleaned = safelist.cleanSrcset(sourceTag, sourceEl, value);
231	                    if (cleaned == null) {
232	                        numDiscarded++;
233	                        continue;
234	                    }
235	                    if (!cleaned.equals(value))
236	                        numDiscarded++; // candidates were dropped or normalized
237	                    value = cleaned;
238	                } else if (Safelist.isStyle(key)) { // clean inline CSS declaration by declaration; drop if none survive
239	                    String cleaned = safelist.cleanStyle(sourceTag, sourceEl, value);
240	                    if (cleaned == null) {
241	                        numDiscarded++;
242	                        continue;
243	                    }
244	                    if (!cleaned.equals(value))
245	                        numDiscarded++; // unsafe or malformed declarations were dropped
246	                    value = cleaned;
247	                } else if (safelist.shouldAbsUrl(sourceTag, key)) { // configured to make absolute urls for this key (href)
248	                    value = sourceEl.absUrl(key);
249	                    if (value.isEmpty()) // could not be made abs; leave as-is to allow custom unknown protocols
250	                        value = sourceAttr.getValue();
251	                }
252	                Range.AttributeRange range = sourceAttrs.sourceRange(key);
253	                destAttrs.put(key, value);
254	                NodeInternals.attributeRange(destAttrs, key, range);
255	            } else
256	                numDiscarded++;
257	        }
258	
259	        Attributes enforcedAttrs = safelist.getEnforcedAttributes(sourceTag);
260	        // special case for <a href rel=nofollow>, only apply to external links:
261	        if (sourceEl.nameIs("a") && enforcedAttrs.get("rel").equals("nofollow")) {
262	            String href = sourceEl.absUrl("href");
263	            if (!href.isEmpty()) {
264	                try {
265	                    URL baseUrl = new URL(sourceEl.baseUri());
266	                    URL linkUrl = new URL(href);
267	                    String baseHost = baseUrl.getHost();
268	                    if (!baseHost.isEmpty() && baseHost.equalsIgnoreCase(linkUrl.getHost())) // same site, so don't set the nofollow
269	                        enforcedAttrs.remove("rel");
270	                } catch (MalformedURLException ignored) {}
271	            }
272	        }
273	
274	        // apply enforced attributes case-insensitively, so a preserved-case source attr is canonicalized to the enforced key
275	        for (Attribute enforcedAttr : enforcedAttrs) {
276	            destAttrs.removeIgnoreCase(enforcedAttr.getKey());
277	            destAttrs.put(enforcedAttr.getKey(), enforcedAttr.getValue());
278	        }
279	        dest.attributes().addAll(destAttrs); // re-attach, if removed in clear
280	        return new ElementMeta(dest, numDiscarded);
281	    }
