534	                    if (code == 0 || code > Character.MAX_CODE_POINT
535	                        || (code >= Character.MIN_SURROGATE && code <= Character.MAX_SURROGATE))
536	                        code = 0xFFFD;
537	                    sb.appendCodePoint(code);
538	                    i = hexEnd;
539	                } else {
540	                    sb.append(value.charAt(i + 1));
541	                    i += 2;
542	                }
