import org.jsoup.safety.*;

public class Probe3 {
    static Safelist sl = Safelist.relaxed().addAttributes(":all", "style");
    static String clean(String html, String base) {
        Document d = Jsoup.parseBodyFragment(html, base);
        return new Cleaner(sl).clean(d).body().html();
    }
    public static void main(String[] a) {
        String[] attacks = {
            "<div style='--x: url(javascript:alert(1));color:red'>x</div>",
            "<div style='--x: URL(JAVASCRIPT:1);color:red'>x</div>",
            "<div style='--x: url(java\\73 cript:1);color:red'>x</div>",
            "<div style='--x: url(java%73cript:1);color:red'>x</div>",
            "<div style='--x: expression(alert(1));color:red'>x</div>",
            "<div style='--x: var(--u, url(vbscript:1));color:red'>x</div>",
            "<div style='--x: \"url(javascript:1)\";color:red'>x</div>",
            "<div style='--x: /* url(javascript:1) */;color:red'>x</div>",
            "<div style='--x: @import \"javascript:1\";color:red'>x</div>",
            "<div style='--x: url(//evil.com/x);color:red'>x</div>",
            "<div style='color:red;background:url(https://ok.com/x)'>x</div>",
            "<div style='color:red;background:url(//evil.com/x)'>x</div>",
            // bare javascript: text (not a reference) is inert, and idempotent re-clean must not resurrect anything
            "<div style='--x: javascript:alert(1);color:red'>x</div>",
        };
        for (String c : attacks) {
            String once = clean(c, "https://example.com/a/b");
            String twice = clean(once, "https://example.com/a/b");
            System.out.println(c + "\n   => " + once + (once.equals(twice) ? "" : "\n   !! NON-IDEMPOTENT: " + twice));
        }
    }
}
